{
  "contract": "AmenoToken",
  "closure": {
    "site_function": "swapAndSendMarketingFee",
    "site_call": ".call",
    "functions": [
      "swapAndSendMarketingFee",
      "transfer",
      "transferFrom"
    ],
    "justification": "These functions interact with the exposed storage 'pendingMarketingFee'."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "transfer",
      "transferFrom"
    ],
    "nesting_bound": {
      "transfer": 1,
      "transferFrom": 1
    }
  },
  "phases": {
    "function": "swapAndSendMarketingFee",
    "pre": {
      "name": "pre",
      "from_marker": "entry",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "exit"
    },
    "linearization_point": "after_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of marketing fees in-flight during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "pendingMarketingFee == snapPre + inFlight",
    "stable_formula": "pendingMarketingFee == snapPre",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "pendingMarketingFee + pendingBurnFee <= _balances[address(this)]",
    "rule": "The exposure invariant ensures that pendingMarketingFee is correctly accounted for during reentrancy, maintaining the target property."
  }
}
